function product_card(array $p): void {$discount=(float)$p['list_price']>0?round((1-(float)$p['sale_price']/(float)$p['list_price'])*100):0;$stock=max(0,(int)($p['stock']??0));?>
<article class="product-card"><a class="product-image" href="index.php?page=chitiet&id=<?=(int)$p['id']?>" aria-label="Xem <?=e($p['name'])?>"><?php if($discount>0):?><span class="badge">Giảm <?=$discount?>%</span><?php endif;?><img src="<?=e(image_url($p))?>" alt="<?=e($p['name'])?>" loading="lazy"></a><div class="product-body"><div class="product-kicker"><span><?=e($p['category_name'])?></span><span><?=e($p['brand'])?></span></div><h3><a href="index.php?page=chitiet&id=<?=(int)$p['id']?>"><?=e($p['name'])?></a></h3><p><?=e($p['description'])?></p><div class="product-price"><strong><?=money($p['sale_price'])?></strong><?php if($discount):?><del><?=money($p['list_price'])?></del><?php endif;?></div><p class="product-stock <?=$stock>0?'in-stock':'out-of-stock'?>" aria-live="polite"><?=$stock>0?'Còn '.number_format($stock).' sản phẩm trong kho':'Tạm hết hàng'?></p><form method="post" action="index.php?page=them_gio" data-cart-add><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><button class="button button-dark full" <?=$stock<1?'disabled':''?>><?=$stock>0?'Thêm vào giỏ':'Hết hàng'?></button></form></div></article>
